ht { text-align: right !important; }.account-cell { display: flex; flex-direction: column; }.account-name { font-weight: 500; }.account-domain { font-size: 11px; color: var(--muted); }.pill { display: inline-block; padding: 2px 8px; border-radius: 999px; font-size: 11px; font-weight: 600; }.pill-green { background: rgb(209, 250, 229); color: rgb(6, 95, 70); }.pill-blue { background: rgb(219, 234, 254); color: rgb(30, 64, 175); }.pill-amber { background: rgb(254, 243, 199); color: rgb(146, 64, 14); }.pill-gray { background: rgb(243, 244, 246); color: rgb(75, 85, 99); }.health { display: flex; align-items: center; gap: 8px; }.health-bar { flex: 1 1 0%; height: 6px; background: rgb(243, 244, 246); border-radius: 3px; overflow: hidden; }.health-fill { height: 100%; }.health-num { font-size: 12px; width: 22px; text-align: right; color: var(--muted); }.owner { display: inline-flex; align-items: center; gap: 8px; }.avatar { width: 22px; height: 22px; border-radius: 50%; color: rgb(255, 255, 255); font-size: 10px; font-weight: 700; display: grid; place-items: center; flex-shrink: 0; }.avatar-placeholder, .skeleton-text, .skeleton-block { background: linear-gradient(90deg, rgb(240, 241, 244), rgb(230, 232, 238), rgb(240, 241, 244)) 0% 0% / 200% 100%; animation: 1.2s ease 0s infinite normal none running shimmer; }.skeleton-text { display: inline-block; width: 90px; height: 10px; border-radius: 4px; }.skeleton-block { height: 80px; border-radius: 8px; margin-bottom: 12px; }@keyframes shimmer { 
